using System.Globalization;
using System.Text.RegularExpressions;

namespace SpecGen;

/// <summary>
/// Generates the mapping of the BCP 47 language tags to the OpenType language system tags of the text shaping from the
/// table of HarfBuzz (tests/Meziantou.Framework.WebPlatform.SpecData/harfbuzz/src/hb-ot-tag-table.hh, MIT license, generated by HarfBuzz from the OpenType language
/// system tag registry and the IANA language subtag registry): the tags of the 2-letter and 3-letter ISO 639 codes, the
/// blocked 3-letter codes, and the rules of the tags with several subtags (<c>hb_ot_tags_from_complex_language</c>, whose
/// conditions are read from its code).
/// </summary>
internal static partial class OpenTypeTagGenerator
{
    public static void Generate(GeneratorContext context)
    {
        var path = context.SpecData("harfbuzz", "src", "hb-ot-tag-table.hh");
        var source = File.ReadAllText(path);
        var writer = new CodeWriter("tests/Meziantou.Framework.WebPlatform.SpecData/harfbuzz/src/hb-ot-tag-table.hh");
        writer.Line("namespace Meziantou.Framework.WebPlatform.Css.Fonts;").Line();
        writer.Line("/// <summary>");
        writer.Line("/// The OpenType language system tags of the BCP 47 language tags, from the table of HarfBuzz (hb-ot-tag-table.hh,");
        writer.Line("/// https://github.com/harfbuzz/harfbuzz, MIT license). See <see cref=\"OpenTypeLanguageTags\"/>.");
        writer.Line("/// </summary>");
        using (writer.Block("internal static partial class OpenTypeLanguageTags"))
        {
            var languages2 = ReadLangTags(source, "ot_languages2");
            writer.Line("/// <summary>The 2-letter ISO 639 codes (as tags padded with spaces, sorted, a code may have several entries) and their OpenType tags.</summary>");
            WriteArray(writer, "Languages2Keys", languages2.Select(l => l.Language));
            WriteArray(writer, "Languages2Values", languages2.Select(l => l.Tag));

            var languages3 = ReadLangTags(source, "ot_languages3");
            writer.Line("/// <summary>The 3-letter ISO 639 codes (sorted) that have one OpenType tag.</summary>");
            WriteArray(writer, "Languages3Keys", languages3.Select(l => l.Language));
            WriteArray(writer, "Languages3Values", languages3.Select(l => l.Tag));

            var multiValues = ReadTags(Block(source, "ot_languages3_multi_values"));
            var multi = new List<(uint Language, int Offset, int Count)>();
            foreach (Match match in LangTagRangeRegex().Matches(Block(source, "ot_languages3_multi")))
            {
                multi.Add((ParseTag(match.Groups["language"].Value), int.Parse(match.Groups["offset"].Value, CultureInfo.InvariantCulture), int.Parse(match.Groups["count"].Value, CultureInfo.InvariantCulture)));
            }

            writer.Line("/// <summary>The 3-letter ISO 639 codes (sorted) that have several OpenType tags: <see cref=\"Languages3MultiValues\"/>[offset..offset + count].</summary>");
            WriteArray(writer, "Languages3MultiKeys", multi.Select(m => m.Language));
            WriteArray(writer, "Languages3MultiOffsets", multi.Select(m => (uint)m.Offset));
            WriteArray(writer, "Languages3MultiCounts", multi.Select(m => (uint)m.Count));
            WriteArray(writer, "Languages3MultiValues", multiValues);

            writer.Line("/// <summary>The 3-letter ISO 639 codes (sorted) that are not OpenType tags although they look like one.</summary>");
            WriteArray(writer, "Languages3Blocked", ReadTags(Block(source, "ot_languages3_blocked")));

            WriteComplexRules(writer, source);
        }

        context.WriteFile(context.Source("Css", "Fonts", "OpenTypeLanguageTags.g.cs"), writer.ToString());
    }

    /// <summary>
    /// Writes the rules of <c>hb_ot_tags_from_complex_language</c>: each rule is a condition on the language tag and its
    /// OpenType tags. The rules before the <c>switch</c> apply to any tag (a variant subtag), the other ones to the tags whose
    /// first character is the <c>case</c> of the switch.
    /// </summary>
    private static void WriteComplexRules(CodeWriter writer, string source)
    {
        var start = source.IndexOf("hb_ot_tags_from_complex_language (", StringComparison.Ordinal);
        var end = source.IndexOf("hb_ot_ambiguous_tag_to_language", start, StringComparison.Ordinal);
        if (start < 0 || end < 0)
            throw new InvalidOperationException("hb_ot_tags_from_complex_language not found");

        var body = source[start..end];
        var switchIndex = body.IndexOf("switch (lang_str[0])", StringComparison.Ordinal);
        var rules = new List<(char First, List<(int Kind, string Value)> Conditions, List<uint> Tags)>();
        var first = '\0';
        var position = 0;
        while (true)
        {
            var ifIndex = body.IndexOf("    if (", position, StringComparison.Ordinal);
            if (ifIndex < 0)
                break;

            // The case of the switch that contains the rule
            if (switchIndex >= 0 && ifIndex > switchIndex)
            {
                var caseIndex = body.LastIndexOf("case '", ifIndex, StringComparison.Ordinal);
                first = caseIndex > switchIndex ? body[caseIndex + 6] : '\0';
            }

            // The check of the length of the first block is not a rule
            var lineEnd = body.IndexOf('\n', ifIndex, StringComparison.Ordinal);
            if (body.AsSpan(ifIndex, lineEnd - ifIndex).Contains("goto out", StringComparison.Ordinal))
            {
                position = lineEnd;
                continue;
            }

            var braceIndex = body.IndexOf('{', ifIndex, StringComparison.Ordinal);
            var condition = body[ifIndex..braceIndex];
            var blockEnd = body.IndexOf("return true;", braceIndex, StringComparison.Ordinal);
            position = blockEnd;

            var conditions = new List<(int Kind, string Value)>();
            foreach (Match match in ConditionRegex().Matches(condition))
            {
                var value = match.Groups["value"].Value;
                var kind = match.Groups["function"].Value switch
                {
                    "lang_matches" => 0,
                    "strcmp" => 1,
                    "strncmp" => 2,
                    _ => 3,
                };

                // The functions other than subtag_matches compare the string from its second character
                conditions.Add((kind, kind == 3 ? value : first + value));
            }

            if (conditions.Count == 0)
                throw new InvalidOperationException("Unknown condition: " + condition);

            var code = CommentRegex().Replace(body[braceIndex..blockEnd], "");
            rules.Add((first, conditions, ReadTags(code)));
        }

        writer.Line("/// <summary>The kinds of the conditions of <see cref=\"ComplexRuleConditionKinds\"/>: 0 the tag starts with the value followed by its end or a hyphen, 1 the tag is the value, 2 the tag starts with the value, 3 the tag contains the value as a subtag.</summary>");
        writer.Line("/// <remarks>The first character of the tag of each rule (0 for the rules that apply to any tag) is <see cref=\"ComplexRuleFirstCharacters\"/>.</remarks>");
        writer.Line($"public static ReadOnlySpan<char> ComplexRuleFirstCharacters => {CodeWriter.Literal(new string([.. rules.Select(r => r.First)]))};").Line();
        WriteArray(writer, "ComplexRuleConditionStarts", Offsets(rules.Select(r => r.Conditions.Count)));
        WriteArray(writer, "ComplexRuleConditionKinds", rules.SelectMany(r => r.Conditions).Select(c => (uint)c.Kind));
        writer.Line("public static readonly string[] ComplexRuleConditionValues =");
        writer.Line("[");
        foreach (var (_, value) in rules.SelectMany(r => r.Conditions))
        {
            writer.Line("    " + CodeWriter.Literal(value) + ",");
        }

        writer.Line("];").Line();
        WriteArray(writer, "ComplexRuleTagStarts", Offsets(rules.Select(r => r.Tags.Count)));
        WriteArray(writer, "ComplexRuleTags", rules.SelectMany(r => r.Tags));

        static IEnumerable<uint> Offsets(IEnumerable<int> counts)
        {
            var offset = 0u;
            yield return 0;
            foreach (var count in counts)
            {
                offset += (uint)count;
                yield return offset;
            }
        }
    }

    private static string Block(string source, string name)
    {
        var start = source.IndexOf(name + "[] = {", StringComparison.Ordinal);
        if (start < 0)
            throw new InvalidOperationException(name + " not found");

        var end = source.IndexOf("};", start, StringComparison.Ordinal);
        return source[(start + name.Length + 6)..end];
    }

    private static List<(uint Language, uint Tag)> ReadLangTags(string source, string name)
    {
        var result = new List<(uint, uint)>();
        foreach (Match match in LangTagRegex().Matches(Block(source, name)))
        {
            result.Add((ParseTag(match.Groups["language"].Value), ParseTag(match.Groups["tag"].Value)));
        }

        return result;
    }

    private static List<uint> ReadTags(string code) => [.. TagRegex().Matches(CommentRegex().Replace(code, "")).Select(match => ParseTag(match.Value))];

    /// <summary>Parses <c>HB_TAG('a','b','c',' ')</c> (or <c>HB_TAG_NONE</c>).</summary>
    private static uint ParseTag(string value)
    {
        if (value == "HB_TAG_NONE")
            return 0;

        var characters = TagCharacterRegex().Matches(value);
        if (characters.Count != 4)
            throw new InvalidOperationException("Invalid tag " + value);

        var tag = 0u;
        foreach (Match character in characters)
        {
            tag = (tag << 8) | character.Groups[1].Value[0];
        }

        return tag;
    }

    private static void WriteArray(CodeWriter writer, string name, IEnumerable<uint> values)
    {
        writer.Line($"public static ReadOnlySpan<uint> {name} =>");
        writer.Line("[");
        writer.Numbers(values, perLine: 12);
        writer.Line("];").Line();
    }

    [GeneratedRegex(@"\{(?<language>HB_TAG\([^)]*\)),\s*(?<tag>HB_TAG\([^)]*\)|HB_TAG_NONE)\}")]
    private static partial Regex LangTagRegex();

    [GeneratedRegex(@"\{(?<language>HB_TAG\([^)]*\)),\s*(?<offset>\d+),\s*(?<count>\d+)\}")]
    private static partial Regex LangTagRangeRegex();

    [GeneratedRegex(@"HB_TAG\([^)]*\)|HB_TAG_NONE")]
    private static partial Regex TagRegex();

    [GeneratedRegex(@"'(.)'")]
    private static partial Regex TagCharacterRegex();

    [GeneratedRegex(@"/\*.*?\*/", RegexOptions.Singleline)]
    private static partial Regex CommentRegex();

    [GeneratedRegex(@"(?<function>lang_matches|strcmp|strncmp|subtag_matches) \([^,]*,\s*(?:limit,\s*)?""(?<value>[^""]*)""")]
    private static partial Regex ConditionRegex();
}
